// Valida la peticion y extrae la pregunta. Corre ANTES del agente a proposito:
// no se gasta una llamada al modelo en una peticion que ya sabemos que es invalida.
//
// Contrato hacia adelante: { __status, cuerpo } si hay que rechazar,
// { __status: 200, pregunta } si hay que seguir.

// Limite de longitud. Va aqui, ANTES de llamar al modelo, porque un prompt se puede
// convencer y un `if` no. Sin esto, cualquiera con el token puede mandar un megabyte
// y quemar la credencial de OpenAI que este flujo comparte con un bot de ventas en
// produccion (ver la anotacion del ADR-0004).
//
// 16000 caracteres son unos 4000 tokens: sobra para pegar un reporte entero, y es 60 veces menos que el megabyte que hoy pasaria.
const MAX_CARACTERES = 16000;

const previo = $input.first().json;

// Si `Autorizar` ya decidio rechazar, se deja pasar su respuesta tal cual.
if (previo.__status !== 200) return [{ json: previo }];

const body = previo.body ?? {};

const error = (code, message, param) => [{
  json: {
    __status: 400,
    cuerpo: { status: 'error', code, respuesta: message, param },
  },
}];

// `model` NO se exige, el flujo fija el modelo.
//
// Tampoco se exigen `id` ni `status` en los items de ENTRADA, por lo mismo:
// el canal puede mandar solo {role, type, content}.

if (body.input === undefined || body.input === null) {
  return error('missing_required_parameter', 'Falta el campo `input`.', 'input');
}

if (typeof body.input !== 'string' && !Array.isArray(body.input)) {
  return error('invalid_type', 'El campo `input` debe ser un string o un array de items.', 'input');
}

if (Array.isArray(body.input)) {
  if (body.input.length === 0) {
    return error('empty_input', 'El campo `input` no puede ser un array vacio.', 'input');
  }
  for (let i = 0; i < body.input.length; i++) {
    const item = body.input[i];
    if (!item || typeof item !== 'object') {
      return error('invalid_item', 'El item ' + i + ' de `input` no es un objeto.', 'input[' + i + ']');
    }
    if (typeof item.type !== 'string' || item.type.length === 0) {
      return error('invalid_item', 'El item ' + i + ' de `input` no declara `type`.', 'input[' + i + '].type');
    }
  }
}

// De un item de tipo message se concatena el texto de sus content parts `input_text`.
function leerInput(input) {
  if (typeof input === 'string') return input;
  const textos = [];
  for (const item of input) {
    if (typeof item.content === 'string') { textos.push(item.content); continue; }
    if (!Array.isArray(item.content)) continue;
    for (const parte of item.content) {
      if (parte && parte.type === 'input_text' && typeof parte.text === 'string') {
        textos.push(parte.text);
      }
    }
  }
  return textos.join('\n');
}

const pregunta = leerInput(body.input);

if (String(pregunta).length > MAX_CARACTERES) {
  return error(
    'input_too_long',
    'El campo `input` supera el limite de ' + MAX_CARACTERES + ' caracteres (llegaron ' +
      String(pregunta).length + '). Manda menos texto o divide la pregunta.',
    'input',
  );
}

if (String(pregunta).trim().length === 0) {
  return error('empty_input', 'El campo `input` no contiene texto.', 'input');
}

// --- Filtro determinista de intento de inyeccion ---
// No reemplaza la resistencia del prompt (esa sigue viva en el system message): esto
// es una alerta que queda REGISTRADA antes de que la peticion llegue al modelo, para
// que un intento de inyeccion se pueda auditar en la tabla `turnos` aunque el modelo
// lo haya resistido perfectamente y no lo mencione en su respuesta. Lo que debe quedar
// registrado no puede depender de que el modelo se acuerde de decirlo.
//
// Es deliberadamente laxo (no bloquea, solo marca): un falso positivo aqui no le
// niega el servicio a nadie, solo aparece marcado en el log para revision.
const GLOSARIO_INYECCION = [
  /ignora\s+(tus\s+)?instruccion/i,
  /olvida\s+(que\s+eres|tus\s+reglas|todo\s+lo\s+anterior)/i,
  /system\s*prompt/i,
  /(dame|dime|revela|muestra|repite).{0,20}(tu\s+)?(prompt|instruccion)/i,
  /actua\s+como\s+(un\s+)?(agente|asistente)\s+sin\s+(restriccion|regla|limite)/i,
  /a\s+partir\s+de\s+ahora\s+eres/i,
  /modo\s+desarrollador/i,
  /jailbreak/i,
  /\bDAN\b/,
];
// Sin quitar acentos, "Actua" (mi regex) no reconoce "Actúa" (lo que escribe la
// gente de verdad). Se normaliza antes de comparar, igual que en los gates de prueba.
const sinAcentos = String(pregunta).normalize('NFD').replace(/[̀-ͯ]/g, '');
const alertaInyeccion = GLOSARIO_INYECCION.some((re) => re.test(sinAcentos));

// --- Deteccion determinista de idioma de la pregunta ---
// Decide con que subconjunto del corpus (es/en) se filtra la recuperacion, para que
// una pregunta en ingles no traiga fragmentos en espanol que el modelo pegaria sin
// traducir (el revoltijo de la ejecucion 72511). No sustituye la regla de espejo del
// prompt: solo elige el idioma de los fragmentos. Empate -> es (idioma fuente).
function detectarIdioma(texto) {
  const t = ' ' + sinAcentos.toLowerCase() + ' ';
  const es = (t.match(/\b(que|de|la|el|los|las|un|una|como|donde|cuando|cuales|cual|quien|por|para|con|sus|su|es|son|ha|hace|hizo|tiene|proyectos|trabajo|experiencia|habla|cuentame|dime|explicame|sobre|tus|del)\b/g) || []).length;
  const en = (t.match(/\b(what|which|who|where|when|how|the|of|is|are|has|have|do|does|did|his|her|their|about|projects|work|experience|tell|explain|your|you|and|for|with|can)\b/g) || []).length;
  return en > es ? 'en' : 'es';
}
const idioma = detectarIdioma(pregunta);

// `previous_response_id` es lo UNICO que llega del pasado: el canal no reenvia
// el historial (ADR-0006). `t0` sirve para medir la latencia del turno completo.
return [{
  json: {
    __status: 200,
    pregunta,
    previous_response_id: typeof body.previous_response_id === 'string' ? body.previous_response_id : '',
    t0: Date.now(),
    alerta_inyeccion: alertaInyeccion,
    idioma,
  },
}];

// Empaqueta la respuesta del agente en el contrato generico {status, response_id, respuesta}.

// El agente devuelve texto VACIO de vez en cuando: es un modelo razonador y en preguntas
// adversarias (inyeccion) llega a gastar su presupuesto razonando sin emitir contenido.
// Medido: 44% con maxTokens 4000, 11% con 8000, 17% con reasoningEffort medium.
//
// Bajar el razonamiento lo evitaba pero rompia otras cosas (el idioma dejaba de reflejar
// al usuario y las consultas multiples a la herramienta se volvian poco fiables, #27), asi
// que el invariante "nunca devolver vacio" NO puede depender del presupuesto del modelo:
// vive aqui, en un if. Igual que los limites del ADR-0002.
const RESPALDO = 'No pude generar una respuesta para eso. Reformula la pregunta y lo intento de nuevo.';
const crudo = $input.first().json.output ?? '';
const texto = String(crudo).trim().length > 0 ? crudo : RESPALDO;

// `crypto` no existe en el sandbox del task runner de n8n.
// El id solo tiene que ser opaco y unico, no criptografico.
const id = (prefijo) =>
  prefijo + '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 12);

const MODELO = 'gpt-5-mini';

// La mantiene sincronizada infra/desplegar-prompt.mjs con prompts/sistema.md (repo HEB-aristo).
// Se registra por turno para poder comparar calidad entre versiones del prompt.
const PROMPT_VERSION = '27';

return [{
  json: {
    __status: 200,
    prompt_version: PROMPT_VERSION,
    cuerpo: { status: 'completed', response_id: id('resp'), respuesta: texto },
  },
}];

// Traduce un fallo del agente a un error con la forma del spec.
//
// Sin este nodo, n8n responde 200 con el CUERPO VACIO cuando algo revienta: un exito
// aparente que esconde el fallo. Medido en la fase 1 con un ReferenceError, y probable
// desde que hay una llamada a un servicio externo de por medio.
//
// El texto crudo del error NUNCA se devuelve: puede traer nombres de nodos, trazas y
// hasta el prompt del sistema. Se usa solo para clasificar.

const crudo = String(
  $input.first().json?.error?.message ??
  $input.first().json?.error ??
  $input.first().json?.message ??
  ''
);

const dice = (...palabras) => palabras.some((p) => crudo.toLowerCase().includes(p));

// 503 y no 502: el Traefik de Easypanel INTERCEPTA los 502 del backend y los sustituye
// por su propia pagina HTML de "Service is not reachable", porque 502 es el codigo que
// el mismo usa cuando un servicio esta caido. Medido: con 502 el cliente recibe HTML;
// con 503 y 504 el cuerpo JSON llega intacto.
let status = 503;
let code = 'upstream_error';
let message = 'El modelo no pudo generar una respuesta. Intentalo de nuevo.';

if (dice('timeout', 'timed out', 'etimedout', 'esockettimedout', 'aborted')) {
  status = 504;
  code = 'upstream_timeout';
  message = 'El modelo tardo demasiado en responder. Intentalo de nuevo.';
} else if (dice('429', 'rate limit', 'quota', 'too many requests')) {
  status = 429;
  code = 'rate_limited';
  message = 'Se alcanzo el limite de peticiones del proveedor. Intentalo en unos momentos.';
} else if (dice('401', '403', 'api key', 'unauthorized', 'incorrect api key')) {
  // Es culpa del servidor, no de quien llama: su bearer ya se valido antes.
  status = 503;
  code = 'upstream_auth_error';
  message = 'El servidor no pudo autenticarse contra el proveedor del modelo.';
}

return [{
  json: {
    __status: status,
    cuerpo: { status: 'error', code, respuesta: message },
  },
}];

// Decide a que conversacion pertenece este turno.
//
// Si no llego `previous_response_id`, se abre una conversacion nueva.
// Si llego y resolvio, se hereda su `conversation_id`.
// Si llego y NO resolvio, se responde 400: callar y empezar de cero seria peor que
// fallar, porque quien pregunta creeria que el asistente perdio la memoria a mitad de la
// conversacion, sin saber por que.
//
// Un id deja de resolver por dos motivos: no existio nunca, o caduco. La limpieza
// borra los turnos de mas de 30 dias (pendiente: limpieza de heb_turnos).

const turno = $('Validar entrada').first().json;

// Lo que ya viene marcado como error pasa intacto hasta el portero unico del final.
// Antes habia un IF aqui delante que lo frenaba; se quito por ser identico al de
// mas abajo, y este nodo se hizo responsable de no estorbar.
if (turno.__status !== 200) return [{ json: turno }];

const fila = $input.first().json ?? {};
const pedido = String(turno.previous_response_id || '').trim();
const encontrado = fila.conversation_id;

// Si la base fallo, `Resolver conversacion` deja pasar su error como item. Se
// distingue de "no encontrado": ahi la culpa es del servidor, no de quien llama,
// y es preferible responder sin memoria a rechazar un id que quiza si existe.
const baseFallo = Boolean(fila.error);

if (pedido && !encontrado && !baseFallo) {
  return [{
    json: {
      __status: 400,
      cuerpo: { status: 'error', code: 'previous_response_not_found', respuesta: 'El `previous_response_id` no existe o ya caduco. Las conversaciones se conservan 30 dias.' },
    },
  }];
}

// --- Limites del guardia determinista ---
// Solo aplican a conversaciones que ya existen: una nueva empieza en cero.
const MAX_TURNOS = 100;        // por conversacion
const MAX_POR_MINUTO = 20;     // por conversacion, para frenar rafagas

if (encontrado) {
  const turnos = Number(fila.turnos ?? 0);
  const ultimoMinuto = Number(fila.ultimo_minuto ?? 0);

  if (turnos >= MAX_TURNOS) {
    return [{
      json: {
        __status: 400,
        cuerpo: { status: 'error', code: 'conversation_too_long', respuesta: 'Esta conversacion alcanzo el limite de ' + MAX_TURNOS +
              ' turnos. Empieza una nueva omitiendo `previous_response_id`.' },
      },
    }];
  }

  if (ultimoMinuto >= MAX_POR_MINUTO) {
    return [{
      json: {
        __status: 429,
        cuerpo: { status: 'error', code: 'rate_limited', respuesta: 'Demasiadas peticiones en esta conversacion: el limite es ' +
              MAX_POR_MINUTO + ' por minuto. Intentalo en unos segundos.' },
      },
    }];
  }
}

const nuevo = () =>
  'conv_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 12);

return [{
  json: {
    __status: 200,
    pregunta: turno.pregunta,
    previous_response_id: pedido,
    conversation_id: encontrado || nuevo(),
    conversacion_nueva: !encontrado,
    t0: turno.t0,
    alerta_inyeccion: turno.alerta_inyeccion ?? false,
    idioma: turno.idioma ?? 'es',
  },
}];

const MODELO_DEL_TURNO = 'gpt-5-mini';
// Empaqueta el turno como JSON en base64, para pasarlo a Postgres en UN solo parametro.
//
// Por que base64 y no varios parametros: n8n parte `queryReplacement` por COMAS, asi que
// cualquier valor con una coma corre las columnas. Es un bug abierto de n8n (#14955,
// reabierto en #16354, cerrado como "not planned"). Lo vimos en vivo: la pregunta acabo
// en la columna `previous_response_id` y la respuesta en `entrada`.
// El base64 no puede contener comas, asi que el problema desaparece de raiz.

// Este nodo cuelga de `Responder`, que se ejecuta TAMBIEN en los caminos de error
// (401, 400, 503). En esos casos `Formatear response` nunca corrio y leerlo revienta,
// dejando la ejecucion marcada como fallida aunque el cliente ya recibio su respuesta
// correcta. El resultado eran errores falsos que enmascaran los de verdad, justo en
// el log que existe para observar el sistema.
//
// Sin turno que registrar, no se registra nada.
if (!$('Formatear response').isExecuted) return [];

const r = $('Formatear response').first().json;
const c = $('Decidir conversacion').first().json;

const registro = {
  response_id: r.cuerpo.response_id,
  conversation_id: c.conversation_id,
  previous_response_id: c.previous_response_id || null,
  entrada: c.pregunta,
  salida: r.cuerpo.respuesta,
  modelo: MODELO_DEL_TURNO,
  prompt_version: r.prompt_version,
  latencia_ms: Date.now() - c.t0,
  alerta_inyeccion: c.alerta_inyeccion ?? false,
};

return [{ json: { registro_b64: Buffer.from(JSON.stringify(registro), 'utf8').toString('base64') } }];

